void sms_menu_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_sms_menu_select_obj_t * p_screen_param;
    lv_obj_t *      list = get_sms_menu_list_obj(ui_Screen);

    ;
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    p_screen_param      = (ui_screen_sms_menu_select_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                {
                    lv_obj_t *      label;

                    label               = lv_obj_get_child(get_focus_obj,1);
                    app_fp_play_tts_menu(lv_label_get_text(label));
                    }
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                {
                    lv_obj_t *      label;

                    label               = lv_obj_get_child(get_focus_obj,1);
                    app_fp_play_tts_menu(lv_label_get_text(label));
                    }
                }
            break;

        case LV_KEY_ENTER:
        case APP_KEY_VALUE_TOP_LEFT:
            {
                switch (child_id)
                {
                    case ENUM_SMS_WRITE:
                        {
                            alv_am_win_enter(NULL,"write",(void *) NULL);
                            }
                        break;

                    case ENUM_SMS_RECIVE:
                        {
                            if (is_tele_sms_data_recive_empty())
                                sms_menu_remind_screen((void *)ui_Screen,child_id);
                            else 
                                alv_am_win_enter(NULL,"list_rev",(void *) NULL);
                            }
                        break;

                    case ENUM_SMS_SEND:
                        {
                            if (is_tele_sms_data_send_empty())
                                sms_menu_remind_screen((void *)ui_Screen,child_id);
                            else 
                                alv_am_win_enter(NULL,"list_send",(void *) NULL);
                            }
                        break;

                    case ENUM_SMS_DRAFT:
                        {
                            if (is_tele_sms_data_draft_empty())
                                sms_menu_remind_screen((void *)ui_Screen,child_id);
                            else 
                                alv_am_win_enter(NULL,"list_draft",(void *) NULL);
                            }
                        break;

                    case ENUM_SMS_DEL:
                        {
                            alv_am_win_enter(NULL,"list_del",(void *) NULL);
                            }
                        break;
                    }
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_app_exit_action(NULL,"sms",NULL);

                //alv_am_app_enter_action(NULL,"home_fp",NULL);
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}


//child_id :1 RECIVE  2:SEND  3:DRAFT
int32_t sms_menu_remind_box_empty(uint8_t child_id)
{
    int32_t         ret = 0;
    uint8_t         buf[6];
    void *          p_param;

    if (child_id)
        p_param = buf;
    else 
        p_param = NULL;

    ret                 = app_msg_send_callback(sms_menu_remind_screen,buf,child_id);

    if (0 != ret) {
        app_loge("[%s] app_msg_send_callback error = %d. \n",__func__,ret);
        }

    return ret;
}



